// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
    const cols = line.split(",").map(c => c.trim());
    const obj = {};
    headers.forEach((h, i) => obj[h] = cols[i] ?? "");

    // Transforma mínimo de string para número
    obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

    return obj;
});

return [{ json: { investimentos } }];

// 1. Recupera os dados de entrada
const dados = $input.first().json;
const clientes = dados.body?.clientes || dados.clientes || [];
const investimentos = dados.investimentos || [];

// 2. Diretrizes humanizadas por perfil
const diretrizes = {
  "Conservador": "priorizar a segurança do seu patrimônio e a previsibilidade da renda fixa",
  "Moderado": "construir um mix equilibrado entre a proteção da renda fixa e o crescimento da renda variável",
  "Arrojado": "maximizar o potencial de retorno a longo prazo com ênfase em ativos de renda variável"
};

// 3. Monta a recomendação consultiva para cada cliente
return clientes.map(cliente => {
  const primeiroNome = cliente.nome.split(" ")[0];
  const opcoes = investimentos.filter(inv => 
    inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()
  );

  // Formata os produtos destacando o valor mínimo de entrada
  const listaProdutos = opcoes.map(inv => {
    const minimoFormatado = Number(inv.minimo).toLocaleString("pt-BR", {
      style: "currency",
      currency: "BRL"
    });
    return `• ${inv.produto} — Aporte mínimo: ${minimoFormatado} | Rentabilidade esperada: ${inv.rentabilidade}`;
  }).join("\n");

  const focoPerfil = diretrizes[cliente.perfil] || "alinhar as melhores oportunidades aos seus planos";

  const mensagemHumanizada = 
`Olá, ${primeiroNome}, tudo bem?

Analisando a sua carteira, identificamos que o seu perfil de investidor é ${cliente.perfil}. O caminho ideal agora é ${focoPerfil}.

Pensando no seu saldo atual de ${cliente.saldo}, selecionamos algumas alternativas sob medida para você começar:

${listaProdutos}

Ficamos à disposição para esclarecer qualquer detalhe e ajudar você a realizar as primeiras aplicações com total tranquilidade!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      mensagem: mensagemHumanizada,
      opcoes_recomendadas: opcoes
    }
  };
});

return $input.all().map(item => {
  // 1. Extrai a string de texto gerada pela IA
  let rawText = item.json.output?.[0]?.content?.[0]?.text || "";

  // 2. Remove eventuais delimitadores de código markdown (```json ... ```)
  rawText = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();

  // 3. Converte a string para objeto JSON
  let emailData = {};
  try {
    emailData = JSON.parse(rawText);
  } catch (error) {
    emailData = {
      to: "",
      subject: "Informações sobre seus investimentos",
      text_body: rawText,
      html_body: `<p>${rawText}</p>`
    };
  }

  // 4. Retorna a estrutura com todos os campos necessários para o Gmail
  return {
    json: {
      to: emailData.to || "",
      subject: emailData.subject || "",
      message: emailData.html_body || emailData.text_body || "",
      html: emailData.html_body || "",
      text: emailData.text_body || ""
    }
  };
});

